"""Render aggregate evidence only; no prediction generation or fitting."""
from core import *
def main():
 out=OUT;v=read(out/'verification.json');d=read(out/'development_decision.json');selection=read(out/'SELECTION.json') if (out/'SELECTION.json').exists() else None
 results={s:read(out/(s+'.json')) for s in ['A_dev','A_test','B_test'] if (out/(s+'.json')).exists()};commands=[read(p) for p in (out/'commands').glob('*.json')]
 resources=dict(cpu_seconds_sampled=sum(x['cpu_seconds_sampled'] for x in commands),peak_rss_bytes_sampled=max(x['peak_rss_bytes_sampled'] for x in commands),wall_seconds_profiled=sum(x['wall_seconds'] for x in commands),optimizer_records=v['optimizer_records'],person_solves=v['person_solves'],shared_fits=sum(m['kind']=='shared' for p in (out/'records').glob('*/expected.json') for m in read(p).values()),sampling_seconds=.05,limitations='Child-process polling can miss final CPU fraction and transient memory peaks. Git, metadata reading and report rendering are not comprehensively profiled.',downloads=0,paid_calls=0,human_fits=0,human_adaptations=0,human_evaluations=0,retries=0)
 qualified={s:all(next(iter(r['gates'].values())).values()) for s,r in results.items() if s!='A_dev'}
 status='QUALIFIED_SYNTHETIC_DIAGNOSTIC' if selection and qualified.get('A_test') and qualified.get('B_test') else (d['status'] if d['status']!='ELIGIBLE' else 'BOUNDED_DIAGNOSTIC_FAILURE')
 summary=dict(status=status,audit_completeness='VERIFIED_OPTIMIZATION',numerical_resolution='PASS' if d['status']!='NUMERICALLY_UNRESOLVED' else 'NUMERICALLY_UNRESOLVED',development=d,heldout_A=qualified.get('A_test','NOT_REACHED'),heldout_B=qualified.get('B_test','NOT_REACHED'),verification=v,resources=resources,results=results)
 atomic(out/'RESOURCE_USAGE.json',resources);atomic(out/'results_summary.json',summary)
 lines=['# Canonical interaction diagnostic v2','',f'Outcome: **{status}**.','',f'Development decision: {d}. Held-out A: {summary["heldout_A"]}; held-out B: {summary["heldout_B"]}.','', '| Stage | rho | Regime | History | Expected gain | Oracle-gap recovery | Contrast NRMSE |','|---|---:|---|---|---:|---:|---:|']
 for stage,r in results.items():
  for x in r['rows']:lines.append(f'| {stage} | {x["rho"]:.12g} | {x["regime"]} | {x["condition"]} | {x["expected_gain"]:.12g} | {x["oracle_gap_recovery"]} | {x["contrast_normalized_rmse"]} |')
 lines+=['','Positive gain is B3 minus M1 expected NLL. Null degradation is the negative of gain. Gates are evaluated without rounding. Detailed B1/B2/B3/M1/oracle realized NLL, accuracy, Brier and expected NLL, plus each initialization, are in the stage JSON files.','',f'Independent saved-array verification: {v["comparisons"]} comparisons, maximum discrepancy {v["max_error"]}; private bytes unchanged. Audit completeness is distinct from person-scaled stationarity and predictive qualification. See certificates and complete optimizer records.','',f'Resources: {resources}.','', 'No original pilot/v1 artifacts were replaced. Original missing pilot development logs remain RECOVERED_SELECTION_ONLY. The v1 null degradation 0.011949302494470126 remains a failure against 0.01.','', 'Interpretation: 96 informative supports in two dimensions; this does not establish performance with 16 supports, 384-dimensional embeddings, natural language or human populations. Initialization seeds are optimization repetitions, not independent data replications. Two realizations cannot establish universal null control. Uninformative histories are an identifiability control, excluded from predictive qualification.','', 'Exposure: PR5 at 6ca2dedc547144d7279696bd5322c1e39c7f03d3 and PR8 at 165bd826f02c91894dc9806d5e49af119eb230a5 were read. DICES and SRO pilot/follow-up outcomes are exposed. The stronger source-blind SRO baseline and inconclusive identity contrast remain separate evidence. TID-8 constituent terms, immutable data identity/overlap and support admission remain unresolved. Scholarly human review is pending; no duplicated source preparation or human work occurred.']
 with (out/'RESULTS.md').open('x',encoding='utf-8') as f:f.write('\n'.join(lines)+'\n')
 nextwork='Propose a separately frozen limited-history and text-representation diagnostic; do not execute it here.' if status=='QUALIFIED_SYNTHETIC_DIAGNOSTIC' else 'Review the failed gates and numerical receipts before proposing another diagnostic. Do not retune this realization, expand the grid or claim human confirmation. No causal diagnosis beyond the reported evidence is established.'
 handoff=f'''# Review checkpoint\n\nStatus: {status}. {nextwork}\n\nRead RESULTS.md, results_summary.json, PROTOCOL.json, verification.json, RESOURCE_USAGE.json and the stage records. Pre-fit and selection publication receipts identify exact public checkpoints; final delivery is the commit containing this handoff. Private cache: C:/Users/David/.cache/decision_functions/interaction_diagnostics_v2. Arrays and complete fitted vectors remain private.\n\nDo not rerun stages into these destinations. Records and files reject collisions; failed attempts consume slots. All results, including failures and unreached stages, are durable. No merge is authorized. Preserve pilot/v1 evidence and the parallel PR5/PR8 exposure ledger. Human confirmation requires a new independent protocol and unresolved admission gates; scholarly review remains separate.\n'''
 with (out/'NEXT_HANDOFF.md').open('x',encoding='utf-8') as f:f.write(handoff)
 print(status)
if __name__=='__main__':main()
